# 1. 3-rect at rows 0-4, cols 3-7 (5x6 block)
# 2. 7-rect A at rows 2-6, cols 14-19 (5x6 block)
# 3. 7-rect B at rows 10-11, cols 4-9 (2x6 block with hole filled at 11,6)
# 4. 7-rect C at rows 11-12, cols 18-19 (2x2 block)
# 5. 2-rect at rows 15-16, cols 7-13 (2x7 block)
# All other cells = 6 (background)

output = []
for r in range(18):
    row = [6] * 23  # Background

    if r in [0, 1, 2, 3, 4] and r >= 0:
        # 3-rect: cols 3-7
