            row[c] = 7

    if r == 12:
        # 7-rect C: cols 18-19 (already set above, but let me be explicit)
        for c in range(18, 20):
            row[c] = 7

    if r in [15, 16]:
        # 2-rect: cols 7-13
        for c in range(7, 14):
            row[c] = 2

    output.append(row)

